//! Reconstructed native ephemeron regressions; NOT executed in recovered cloud.
use super::*;use crate::core::{gc::{Context,RootSet},object::{NIL,ObjectType,Symbol},cons::Cons};use rune_core::macros::root;
fn ht(o:Object<'_>)->&LispHashTable{let ObjectType::HashTable(t)=o.untag()else{unreachable!()};t}
#[test]fn dead_cycles_do_not_self_retain_in_either_mode(){for mode in [HashTableWeakness::Key,HashTableWeakness::Value]{let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(table,cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,mode)),cx);{root!(key,Cons::new1(NIL,cx),cx);root!(value,Cons::new1(key.bind(cx),cx),cx);key.bind(cx).set_car(value.bind(cx).into()).unwrap();ht(table.bind(cx)).insert(key.bind(cx).into(),value.bind(cx).into()).unwrap();cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).len(),1);}cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).len(),0);cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).len(),0);}}
#[test]fn only_conditional_side_external_root_activates_without_backrefs(){for mode in [HashTableWeakness::Key,HashTableWeakness::Value]{for root_key in [false,true]{let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(table,cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,mode)),cx);root!(external,Cons::new1(NIL,cx),cx);let other=Cons::new1(NIL,cx);let(key,value)=if root_key{(external.bind(cx).into(),other.into())}else{(other.into(),external.bind(cx).into())};ht(table.bind(cx)).insert(key,value).unwrap();cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).len(),usize::from(root_key==(mode==HashTableWeakness::Key)));}}}
#[test]fn immediates_are_live_only_on_conditional_side(){for mode in [HashTableWeakness::Key,HashTableWeakness::Value]{let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(table,cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,mode)),cx);ht(table.bind(cx)).insert(cx.add(7),Cons::new1(NIL,cx).into()).unwrap();ht(table.bind(cx)).insert(Cons::new1(NIL,cx).into(),cx.add(8)).unwrap();cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).len(),1);cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).len(),1);}}
#[test]fn weak_key_cross_table_fixedpoint_and_hidden_table(){let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(a,cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,HashTableWeakness::Key)),cx);root!(b,cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,HashTableWeakness::Key)),cx);{root!(k1,Cons::new1(NIL,cx),cx);let k2=Cons::new1(NIL,cx);ht(a.bind(cx)).insert(k1.bind(cx).into(),Cons::new1(k2,cx).into()).unwrap();ht(b.bind(cx)).insert(k2.into(),Cons::new1(k1.bind(cx),cx).into()).unwrap();cx.garbage_collect(true);assert_eq!(ht(a.bind(cx)).len(),1);assert_eq!(ht(b.bind(cx)).len(),1);}cx.garbage_collect(true);assert_eq!(ht(a.bind(cx)).len(),0);assert_eq!(ht(b.bind(cx)).len(),0);let inner=cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,HashTableWeakness::Key));ht(inner).insert(cx.add(7),Cons::new1(NIL,cx).into()).unwrap();ht(a.bind(cx)).insert(NIL,inner).unwrap();cx.garbage_collect(true);let inner=ht(a.bind(cx)).get(NIL).unwrap().unwrap();assert_eq!(ht(inner).len(),1);}
#[test]fn weak_value_cross_table_fixedpoint_and_hidden_table(){let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(a,cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,HashTableWeakness::Value)),cx);root!(b,cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,HashTableWeakness::Value)),cx);{root!(v1,Cons::new1(NIL,cx),cx);let v2=Cons::new1(NIL,cx);ht(a.bind(cx)).insert(Cons::new1(v2,cx).into(),v1.bind(cx).into()).unwrap();ht(b.bind(cx)).insert(Cons::new1(v1.bind(cx),cx).into(),v2.into()).unwrap();cx.garbage_collect(true);assert_eq!(ht(a.bind(cx)).len(),1);assert_eq!(ht(b.bind(cx)).len(),1);}cx.garbage_collect(true);assert_eq!(ht(a.bind(cx)).len(),0);assert_eq!(ht(b.bind(cx)).len(),0);let inner=cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,HashTableWeakness::Value));ht(inner).insert(Cons::new1(NIL,cx).into(),cx.add(7)).unwrap();ht(a.bind(cx)).insert(inner,NIL).unwrap();cx.garbage_collect(true);let inner=ht(a.bind(cx)).get_index(0).unwrap().0;assert_eq!(ht(inner).len(),1);}
#[test]fn stored_identity_not_equal_replacement_drives_liveness(){let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(table,cx.add(HashTable::with_test_and_weakness(HashTableTest::Equal,HashTableWeakness::Key)),cx);root!(replacement,cx.add("same"),cx);ht(table.bind(cx)).insert(cx.add("same"),NIL).unwrap();assert!(ht(table.bind(cx)).get(replacement.bind(cx)).unwrap().is_some());assert!(ht(table.bind(cx)).clone_in(&cx.block).is_err());cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).len(),0);root!(own,cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,HashTableWeakness::Key)),cx);ht(own.bind(cx)).insert(own.bind(cx),Cons::new1(NIL,cx).into()).unwrap();cx.garbage_collect(true);assert_eq!(ht(own.bind(cx)).len(),1);}
#[test]fn pruning_prior_entry_corrects_live_iteration_cursor(){let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(table,cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,HashTableWeakness::Key)),cx);ht(table.bind(cx)).insert(Cons::new1(NIL,cx).into(),NIL).unwrap();root!(current,Cons::new1(NIL,cx),cx);root!(later,Cons::new1(NIL,cx),cx);ht(table.bind(cx)).insert(current.bind(cx).into(),NIL).unwrap();ht(table.bind(cx)).insert(later.bind(cx).into(),NIL).unwrap();ht(table.bind(cx)).set_iter_index(2);cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).get_iter_index(),1);assert!(ht(table.bind(cx)).get_index(1).unwrap().0.ptr_eq(Object::from(later.bind(cx))));}
#[test]fn weak_only_native_endpoint_payload_finalizes_once(){use crate::{channel_manager::{ChannelManager,RecvError},core::object::make_channel_pair_for_test};for mode in [HashTableWeakness::Key,HashTableWeakness::Value]{let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(table,cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,mode)),cx);let manager=ChannelManager::isolated_for_test();let(id,sender,receiver)=make_channel_pair_for_test(manager.clone(),1);let sender=cx.add(sender);ht(table.bind(cx)).insert(Cons::new1(NIL,cx).into(),sender).unwrap();cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).len(),0);assert_eq!(manager.counts_for_test(id),Some((0,1)));assert!(matches!(receiver.try_recv(cx),Err(RecvError::Closed)));cx.garbage_collect(true);assert_eq!(manager.counts_for_test(id),Some((0,1)));receiver.close();}}
#[test]fn moving_uninterned_and_global_symbols_have_distinct_liveness(){let roots=RootSet::default();let cx=&mut Context::new(&roots);root!(table,cx.add(HashTable::with_test_and_weakness(HashTableTest::Eq,HashTableWeakness::Key)),cx);{root!(key,Symbol::new_uninterned("weak-local",&cx.block),cx);ht(table.bind(cx)).insert(key.bind(cx).into(),Cons::new1(NIL,cx).into()).unwrap();cx.garbage_collect(true);assert!(ht(table.bind(cx)).get(key.bind(cx).into()).unwrap().is_some());}ht(table.bind(cx)).insert(crate::core::object::TRUE,Cons::new1(NIL,cx).into()).unwrap();cx.garbage_collect(true);assert_eq!(ht(table.bind(cx)).len(),1);assert!(ht(table.bind(cx)).get(crate::core::object::TRUE).unwrap().is_some());}
